from __future__ import absolute_import

import time
from collections import OrderedDict
from taf.ul.oam.selenium_rap_manager.common import TabBar, LocalBasicPage
from selenium.webdriver.common.by import By
from taf.ul.oam.selenium_rap_manager.modals import ConfirmationModal
from taf.ul.oam.selenium_rap_manager.exceptions import CertificateRevocationUnconfigurableError


class Certificates(LocalBasicPage):
    _BTS_CERTIFICATES_TAB_XPATH = '//li[contains(@id, "operator-certificates-tab active")]'
    _UPLOAD_FILE_BUTTON_ID = 'bts-certificate-input-file'
    _CERTIFICATE_PASSWORD_INPUT_XPATH = "//input[@id='operator-certificate-password-input']"
    _CERTIFICATE_INSTALL_BUTTON_ID = 'install-operator-certs'
    _CERT_REVOCATION_LISTS_TAB = 'certificate-revocation-lists-tab'
    _CRL_DISTRIBUTION_POINTERS_TXT_XPATH = '//*[@id="crl-additional-points-text"]'
    _CRL_DISTRIBUTION_POINTERS_CANCEL_XPAH = '//*[@id="contenttablecrl-distribution-grid"]' \
                                             '//span[contains(@class, "icon-cancel")]'
    _CRL_DISTRIBUTION_POINTERS_PRIMARIY_INPUT_XPATH = '//*[@id="textboxeditorcrl-distribution-gridprimaryAddress"]'
    _CRL_DISTRIBUTION_POINTERS_SECONDARY_INPUT_XPATH = '//*[@id="textboxeditorcrl-distribution-gridsecondaryAddress"]'
    _CRL_SOURCE_SELECTLIST_XPATH = '//*[@id="crl-source-selectlist"]'
    _CRL_ENABLE_CHECKBOX_XPATH = "//*[@id='crl-checkbox-input']"
    _CRL_UPDATE_INTERVAL_ID = 's-normal'
    _CRL_UPDATE_BUTTON_XPATH = '//*[@id="crl-update-button"]'

    _CMP_SERVER_SETTINGS = '//*[@id="cmp-server-settings-tab"]/a'
    _CMP_UPDATE_STATUS = '//*[@id="cmp-update-status-element"]/span[@class="cmp-update-status"]'
    _CMP_IP_ADDRESS_INPUT_ID = 'cmp-ip-address-input'
    _CMP_PORT_INPUT_ID = 'cmp-port-input'
    _CMP_DIRECTORY_INPUT_ID = 'cmp-directory-input'
    _CMP_CA_SUBJECT_NAME_INPUT_ID = 'cmp-ca-subject-name-input'
    _CMP_REFERENCE_NUMBER__INPUT_ID = 'cmp-refnum-input'
    _CMP_PRE_SHARED_KEY_INPUT_ID = 'cmp-psk-input'
    _CMP_UPDATE_BUTTON_ID = 'cmp-update-btn'
    _CMP_INIT_CERTIFICATES_ID = 'manual-init-certificates-btn'
    _CMP_CONFIRMATION_MODAL_CONFIRM_BOTTON_ID = 'confirmation-modal-confirm'
    _CMP_STATUS = '//*[@id="cmp-state-label-value"]'
    _CMP_INIT_CERTIFICATES_STATUS = '//button[@id="manual-init-certificates-btn"]/following-sibling::*[@class="manual-init-status"]'

    def __init__(self, driver):
        super(Certificates, self).__init__(driver)
        self._tab_bar = TabBar(driver)
        self._tab_bar.click_certificates()

    def _upload_certificate_file(self, file_path):
        display_button = "document.getElementById(\"{}\").style.opacity=1;".format(self._UPLOAD_FILE_BUTTON_ID)
        revise_button_position = "document.getElementById(\"{}\").style.left='50%';".format(self._UPLOAD_FILE_BUTTON_ID)
        hide_button = "document.getElementById(\"{}\").style.opacity=0;".format(self._UPLOAD_FILE_BUTTON_ID)
        self.execute_script(display_button)
        self.execute_script(revise_button_position)
        self.insert_text_to_enable_element((By.ID, self._UPLOAD_FILE_BUTTON_ID), file_path)
        self.execute_script(hide_button)

    def install_certificate(self, file_path, password):
        self.click_enabled_element((By.XPATH, self._BTS_CERTIFICATES_TAB_XPATH))
        self._upload_certificate_file(file_path)
        self.insert_text_to_enable_element((By.XPATH, self._CERTIFICATE_PASSWORD_INPUT_XPATH), password)
        self.click_enabled_element((By.ID, self._CERTIFICATE_INSTALL_BUTTON_ID))

    def _clear_distribution_pointers(self):
        while self.check_if_exists((By.XPATH, self._CRL_DISTRIBUTION_POINTERS_CANCEL_XPAH)):
            self.click_element_by_xpath(self._CRL_DISTRIBUTION_POINTERS_CANCEL_XPAH)

    def _click_crl_title_element(self):
        self.click_element_by_xpath(self._CRL_DISTRIBUTION_POINTERS_TXT_XPATH)
        time.sleep(1)

    def _input_secondary_value(self, row_xpath, value=None):
        secondary_address_xpath = row_xpath + '//div[3]'
        value = value if value else ''

        self.click_element_by_xpath(secondary_address_xpath)
        self.insert_text_to_enable_element((By.XPATH, self._CRL_DISTRIBUTION_POINTERS_SECONDARY_INPUT_XPATH), value, 5)
        self._click_crl_title_element()

    def _input_primary_value(self, row_xpath, value=None):
        primary_address_xpath = row_xpath + '//div[2]'
        value = value if value else ''

        self.click_element_by_xpath(primary_address_xpath)
        self.insert_text_to_enable_element((By.XPATH, self._CRL_DISTRIBUTION_POINTERS_PRIMARIY_INPUT_XPATH), value, 5)
        self._click_crl_title_element()

    def _input_distribution_pointers(self, distribution_list):
        for index, item in enumerate(distribution_list):
            row_xpath = '//*[@id="row{}crl-distribution-grid"]'.format(index)
            self._input_primary_value(row_xpath, item[0])
            self._input_secondary_value(row_xpath, item[1])

    def _select_crl_source(self, crl_source):
        crl_source_arrow_down_xpath = self._CRL_SOURCE_SELECTLIST_XPATH + '/button[2]'
        crl_source_xpath = ''.join([self._CRL_SOURCE_SELECTLIST_XPATH,
                                    '/ul/li//span[contains(text(), "{}")]'.format(crl_source)])

        self.click_element_by_xpath(crl_source_arrow_down_xpath)
        self.wait_for_visibility((By.XPATH, crl_source_xpath))
        self.click_element_by_xpath(crl_source_xpath)

    def update_certificate_revocation_list(self, crl_update_interval, crl_source, distribution_list):
        self.wait_for_visibility((By.ID, self._CERT_REVOCATION_LISTS_TAB))
        self.click_enabled_element((By.ID, self._CERT_REVOCATION_LISTS_TAB))

        self._check_vnf_status()

        self.select_checkbox_by_xpath(self._CRL_ENABLE_CHECKBOX_XPATH)
        self.insert_text_to_enabled_field((By.ID, self._CRL_UPDATE_INTERVAL_ID), crl_update_interval, 5)
        self._select_crl_source(crl_source)

        self._clear_distribution_pointers()
        self._input_distribution_pointers(distribution_list)

        self.click_element_by_xpath(self._CRL_UPDATE_BUTTON_XPATH)

    def _cert_row_is_expanded(self, current_row_xpath):
        arrow_expanded = current_row_xpath + "//span[contains(@class, 'jqx-icon-arrow-down')]"
        return self.check_if_visible((By.XPATH, arrow_expanded), 3)

    def _expand_row(self, row_xpath):
        if self._arrow_in_row(row_xpath) and not self._cert_row_is_expanded(row_xpath):
            elem = self._driver.find_element_by_xpath(row_xpath + '//td')
            elem.location_once_scrolled_into_view
            elem.click()

    def _arrow_in_row(self, row_xpath):
        arrow_span = row_xpath + "//span[contains(@class, 'jqx-icon-arrow-')]"
        return self.check_if_visible((By.XPATH, arrow_span), 3)

    @staticmethod
    def _get_tr_xpath_following_root_by_level(root_row_xpath, level):
        return root_row_xpath + '/following::tr[position()={index}]'.format(index=level - 1)

    def _expand_row_between_root_target(self, root_row_xpath, target_level):
        self._expand_row(root_row_xpath)

        if target_level < 2:
            return None

        transition_index = 2
        while transition_index < target_level:
            transition_row_xpath = self._get_tr_xpath_following_root_by_level(root_row_xpath, transition_index)
            self._expand_row(transition_row_xpath)
            transition_index = transition_index + 1

    def _click_to_target_element(self, root_type_xpath, target_level):
        root_row_xpath = root_type_xpath + "/.."

        if target_level == 1:
            self.click_element_by_xpath(root_type_xpath)
        else:
            self._expand_row_between_root_target(root_row_xpath, target_level)
            target_xpath = self._get_tr_xpath_following_root_by_level(root_row_xpath, target_level) + '//td'
            self.click_element_by_xpath(target_xpath)

    def _get_cert_info(self):
        """
        Get BTS cert info info at BTS Certificates tab
        :return: OrderedDict
        """
        operator_cert_details_fields_xpath = "//div[@id='operator-cert-details']//tbody//td[1]"
        operator_cert_details_values_xpath = "//div[@id='operator-cert-details']//tbody//td[2]"
        self.wait_for_visibility((By.XPATH, operator_cert_details_fields_xpath))
        cert_filed = [elem.text for elem in self._driver.find_elements_by_xpath(operator_cert_details_fields_xpath)]
        values = [elem.text for elem in self._driver.find_elements_by_xpath(operator_cert_details_values_xpath)]
        return OrderedDict(zip(cert_filed, values))

    def get_cert_detail(self, field=None, root_type='TA', root_type_index=1, target_level=1):
        if not root_type or target_level < 1:
            return {}

        root_type_xpath = "(//div[@id='contenttableoperator-cert-grid']//tr" \
                          "//td[text()='{root_type}'])[{root_type_index}]" \
            .format(root_type=root_type, root_type_index=root_type_index)

        self.wait_for_visibility((By.XPATH, self._BTS_CERTIFICATES_TAB_XPATH))
        self.click_enabled_element((By.XPATH, self._BTS_CERTIFICATES_TAB_XPATH))

        locator = (By.XPATH, root_type_xpath)
        self.wait_for_visibility(locator)

        self._click_to_target_element(root_type_xpath, target_level)

        cert_detail = self._get_cert_info()
        return cert_detail[field] if field else cert_detail

    def initialize_certificates(self, ip, port, directory, ca_subject_name, ref_num, pre_shared_key, timeout):
        self.click_enabled_element((By.XPATH, self._CMP_SERVER_SETTINGS))
        self._check_vnf_status()
        self.insert_text_to_enable_element((By.ID, self._CMP_IP_ADDRESS_INPUT_ID), ip)
        self.insert_text_to_enable_element((By.ID, self._CMP_PORT_INPUT_ID), port)
        self.insert_text_to_enable_element((By.ID, self._CMP_DIRECTORY_INPUT_ID), directory)
        self.insert_text_to_enable_element((By.ID, self._CMP_CA_SUBJECT_NAME_INPUT_ID), ca_subject_name)
        self.insert_text_to_enable_element((By.ID, self._CMP_REFERENCE_NUMBER__INPUT_ID), ref_num)
        self.insert_text_to_enable_element((By.ID, self._CMP_PRE_SHARED_KEY_INPUT_ID), pre_shared_key)
        self.click_enabled_element((By.ID, self._CMP_UPDATE_BUTTON_ID))
        self.wait_for_visibility((By.XPATH, self._CMP_UPDATE_STATUS), 60)
        self.click_enabled_element((By.ID, self._CMP_INIT_CERTIFICATES_ID))
        self.wait_for_visibility((By.ID, self._CMP_CONFIRMATION_MODAL_CONFIRM_BOTTON_ID), 5)
        ConfirmationModal(self._driver).confirm()
        result = self._wait_until_certificates_initialization_finished(timeout)
        return result

    def _wait_until_certificates_initialization_finished(self, timeout):
        self._is_text_present_in_element((By.XPATH, self._CMP_INIT_CERTIFICATES_STATUS), 'Initializing certificates completed', timeout)
        return self.wait_for_text_change((By.XPATH, self._CMP_STATUS), 'Initialization ongoing', timeout)

    def _check_vnf_status(self):
        vnf_connection_status_text_id = 'vnf-connection-status-text'
        if self.check_if_element_has_text((By.ID, vnf_connection_status_text_id), 'Connected'):
            raise CertificateRevocationUnconfigurableError('no access to data because connected to VNF')
